import os
from typing import Any, Dict, List, Optional, Union

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


def _field_value(field: Any) -> Any:
    if field is None:
        return None
    if getattr(field, "value", None) is not None:
        return field.value
    if getattr(field, "content", None) is not None:
        return field.content
    return None


def _normalize_line_item(item_field: Any) -> Dict[str, Any]:
    result: Dict[str, Any] = {}
    value_object = getattr(item_field, "value_object", None)
    if not value_object:
        return result

    for key, subfield in value_object.items():
        result[key] = _field_value(subfield)
    return result


def extract_invoice_fields(
    document: Union[str, bytes],
    *,
    endpoint: Optional[str] = None,
    api_key: Optional[str] = None,
) -> Dict[str, Any]:
    endpoint = endpoint or os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    api_key = api_key or os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(api_key),
    )

    if isinstance(document, str):
        with open(document, "rb") as f:
            document_bytes = f.read()
    else:
        document_bytes = document

    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        body=document_bytes,
    )
    result = poller.result()

    if not result.documents:
        return {
            "vendor": None,
            "date": None,
            "total": None,
            "line_items": [],
        }

    doc = result.documents[0]
    fields = doc.fields or {}

    vendor = None
    vendor_name_field = fields.get("VendorName")
    if vendor_name_field is not None:
        vendor = _field_value(vendor_name_field)

    date = None
    invoice_date_field = fields.get("InvoiceDate")
    if invoice_date_field is not None:
        date = _field_value(invoice_date_field)

    total = None
    invoice_total_field = fields.get("InvoiceTotal")
    if invoice_total_field is not None:
        total = _field_value(invoice_total_field)

    line_items: List[Dict[str, Any]] = []
    items_field = fields.get("Items")
    if items_field and getattr(items_field, "value_array", None):
        for item in items_field.value_array:
            line_items.append(_normalize_line_item(item))

    return {
        "vendor": vendor,
        "date": date.isoformat() if hasattr(date, "isoformat") else date,
        "total": total,
        "line_items": line_items,
    }
